// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        bool ok2;
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        uint256 balAfter = address(c).balance;

        assertTrue(!(ok == true) || (ok2 == true && balAfter == balBefore));
    }
}
